CREATE TABLE IF NOT EXISTS `__DATABASE__`.ivis_kumec_history (`event_id` FixedString(64), `run_id` String, `record_kind` LowCardinality(String), `entity_id` String, `kind` LowCardinality(String), `uid` String, `source_uid` String, `resource_version` String, `cluster_uid` String, `cluster_name` String, `namespace` String, `name` String, `component` LowCardinality(String), `operation` LowCardinality(String), `after_state` String, `source_position` String, `observed_time` String, `recorded_ns` UInt64, `inserted_at` DateTime64(3, 'UTC') DEFAULT now64(3)) ENGINE = ReplacingMergeTree ORDER BY (run_id, entity_id, component, event_id) SETTINGS index_granularity = 8192;
